package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
public class LocalAutomationTest {
 @Test public void plansFavoritesShuffleAndTimerWithoutLosingArtistConjunction(){LocalAutomation.Plan p=LocalAutomation.parse("toque minhas favoritas em ordem aleatória e pare em 30 minutos");assertTrue(p.summary(),p.valid());assertEquals(3,p.commands.size());assertEquals(VoiceCommand.Action.FAVORITES,p.commands.get(0).action);assertEquals(VoiceCommand.Action.SHUFFLE_ON,p.commands.get(1).action);assertEquals(30,p.commands.get(2).minutes);p=LocalAutomation.parse("toque Chitãozinho e Xororó; repita esta faixa");assertTrue(p.valid());assertEquals("Chitãozinho e Xororó",p.commands.get(0).query);assertEquals(VoiceCommand.Action.REPEAT_ONE,p.commands.get(1).action);}
 @Test public void searchesHaveExplicitDestinationsAndPreserveAccents(){LocalAutomation.Plan p=LocalAutomation.parse("pesquise Chitãozinho e Xororó no YouTube");assertTrue(p.valid());assertEquals(LocalAutomation.Destination.YOUTUBE,p.destination);assertEquals("Chitãozinho e Xororó",p.query);p=LocalAutomation.parse("imagens de boa noite");assertEquals(LocalAutomation.Destination.IMAGES,p.destination);assertEquals("boa noite",p.query);}
 @Test public void refusesUnknownEmptyAndOverlongPlansInsteadOfExecutingPartialActions(){for(String phrase:new String[]{"", "exclua todos os arquivos", "pause; apague o celular", "pause;", "pause;pause;pause;pause;pause;pause;pause", "abra YouTube; pause", "pause; toque minhas favoritas", "x".repeat(601)})assertFalse(phrase,LocalAutomation.parse(phrase).valid());}
 @Test public void allBuiltInPresetsAndNavigationAreSupported(){for(String phrase:new String[]{"toque minhas favoritas; desative o modo aleatório; pare em 30 minutos","toque minhas favoritas; ative o modo aleatório","abrir PDF","abra central inteligente","continue; não repetir; pare após três músicas"})assertTrue(phrase,LocalAutomation.parse(phrase).valid());}
 @Test public void literalSearchTitlesCannotTurnIntoControlActions(){assertFalse(LocalAutomation.parse("pesquise pause").valid());LocalAutomation.Plan p=LocalAutomation.parse("toque Pause");assertEquals(VoiceCommand.Action.PLAY_QUERY,p.commands.get(0).action);assertEquals("Pause",p.commands.get(0).query);assertFalse(LocalAutomation.parse("pesquise algo; pause no YouTube").valid());}
 @Test public void navigationPreviewUsesPortugueseScreenNames(){assertTrue(LocalAutomation.parse("abrir PDF").summary().contains("Leitor de PDF"));assertTrue(LocalAutomation.parse("abrir minhas frases").summary().contains("Minhas frases"));}

}
